s=s[:pos]+'''async function documentStore(){return new Promise<IDBDatabase>((resolve,reject)=>{const request=indexedDB.open('supplyo-documents',1);request.onupgradeneeded=()=>request.result.createObjectStore('files');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function saveDocument(file:File,id:string){const db=await documentStore();await new Promise<void>((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)});db.close()}
async function openDocument(id:string){try{const db=await documentStore();const file=await new Promise<File>((resolve,reject)=>{const r=db.transaction('files').objectStore('files').get(id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});db.close();if(!file){toast.error('Файл не найден в этом браузере');return}const url=URL.createObjectURL(file);const a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch{toast.error('Не удалось открыть документ')}}
'''+s[pos:]
s=s.replace('<DialogFooter><Button type="button" variant="outline" onClick={()=>setDraft(null)}>','<DialogFooter><Button type="button" variant="outline" onClick={()=>setDraft(null)}>')
